using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class ShopOrdersPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("ShopOrders", "View"); return AdminDataService.GetList("ShopOrders"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("ShopOrders", "View"); return AdminDataService.GetDefinitionMetadata("ShopOrders"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("ShopOrders", "Delete"); return AdminDataService.Delete("ShopOrders", id); } } }
